import{z as o,x as s,o as e,c as l,q as A,j as n,D as a,d as i,s as r,S as t}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"库存极限与降风险","description":"","frontmatter":{"title":"库存极限与降风险","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/mm-inventory-limits.md","filePath":"quant/mm-inventory-limits.md","lastUpdated":1791063341000}'),d={name:"quant/mm-inventory-limits.md"};function m(p,E,c,F,C,D){const B=s("Mermaid");return e(),l("div",null,[E[2]||(E[2]=A('<h1 id="库存极限与降风险" tabindex="-1">库存极限与降风险 <a class="header-anchor" href="#库存极限与降风险" aria-label="Permalink to &quot;库存极限与降风险&quot;">​</a></h1><div class="epigraph"><p>降风险是拿确定性的小亏，换掉潜在的更大亏；行动的顺序要事先写好，触限时没有「现想」的位置。</p><footer>—— 据 Ho and Stoll, Journal of Financial Economics, 1981；Easley, López de Prado and O&#39;Hara, 2012 整理</footer></div><p><a href="/quant/mm-risk-limits">上一课</a>把限额架在报价引擎前，越界侧会被关掉。但「关一侧」只是不再变差：库存已经贴在限额上，每多持一秒都在付方差。本课写降风险的选项排序——从最便宜到最贵的减仓路径，与每条路径的成本核算。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>触限后的行动集合有六个：加重偏度、只报减仓侧、主动吃单过价差（crossing）、对冲腿转移、参与拍卖或大宗、暂停策略。排序依据是成本-速度谱：偏度最慢最便宜，crossing 最快最贵。两种对称的死法：全用最贵路径，每次触限都吃价差，减仓成本把做市收入吃光；全用最慢路径，库存方差把期望收入磨没，还占满限额让策略停摆。缺的是一张预先写好、演练过的阶梯，以及每级台阶的成本标价。</p>',5)),(e(),n(t,null,{default:a(()=>[r(B,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E5%BA%93%E5%AD%98%E8%B4%B4%E9%99%90%EF%BC%8C%E9%80%89%E5%93%AA%E6%9D%A1%E5%87%8F%E4%BB%93%E8%B7%AF%E5%BE%84%EF%BC%9F%22%7D%20--%3E%20SKEW%5B%22%E5%8A%A0%E9%87%8D%E5%81%8F%E5%BA%A6%EF%BC%9A%E6%9C%80%E6%85%A2%EF%BC%8C%E5%8F%AA%E4%BB%98%E8%AE%A9%E4%BB%B7%EF%BC%8C%E5%88%86%E9%92%9F%E5%88%B0%E5%B0%8F%E6%97%B6%22%5D%0A%20%20Q%20--%3E%20ONE%5B%22%E5%8D%95%E5%90%91%E6%8A%A5%E4%BB%B7%EF%BC%9A%E9%80%80%E5%87%BA%E9%80%86%E5%8A%BF%E4%BE%A7%EF%BC%8C%E9%80%9F%E5%BA%A6%E4%B8%AD%E7%AD%89%22%5D%0A%20%20Q%20--%3E%20CROSS%5B%22%E4%B8%BB%E5%8A%A8%E5%90%83%E5%8D%95%EF%BC%9A%E6%9C%80%E5%BF%AB%EF%BC%8C%E4%BB%98%E5%85%A8%E9%A2%9D%E4%BB%B7%E5%B7%AE%E5%8A%A0%E5%A4%9A%E6%A1%A3%E5%86%B2%E5%87%BB%22%5D%0A%20%20Q%20--%3E%20HEDGE%5B%22%E5%AF%B9%E5%86%B2%E8%85%BF%E8%BD%AC%E7%A7%BB%EF%BC%9A%E5%BF%AB%EF%BC%8C%E4%BD%86%E5%8F%97%E5%9F%BA%E5%B7%AE%E4%B8%8E%E4%BF%9D%E8%AF%81%E9%87%91%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20Q%20--%3E%20AUCTION%5B%22%E6%8B%8D%E5%8D%96%20%2F%20%E5%A4%A7%E5%AE%97%EF%BC%9A%E6%8A%98%E4%BB%B7%E6%98%AF%E5%BA%93%E5%AD%98%E8%BD%AC%E7%A7%BB%E7%9A%84%E4%BB%B7%E6%A0%BC%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[i(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<h3 id="成本-速度谱" tabindex="-1">成本-速度谱 <a class="header-anchor" href="#成本-速度谱" aria-label="Permalink to &quot;成本-速度谱&quot;">​</a></h3><p>偏度：只动价格不动账，成本是收入侧的让价，速度以分钟到小时计。单向报价（只报减仓方向）：退出逆势侧，成本是对称性损失，速度中等。crossing：支付全额有效价差并消耗多档深度，按<a href="/quant/effective-realized-spread">有效与实现价差</a>口径核算，速度最快。对冲腿：受基差、保证金与腿上容量约束，见<a href="/quant/mm-hedging-inventory">对冲与库存转移</a>。拍卖与大宗：把库存转让给愿意持有的人，折价是转移价格，路径见<a href="/quant/auction-execution">竞价执行</a>。</p><p><span class="marginnote">crossing 的真实成本不止半个价差：按逐档消耗核算，名义一档价差的品种，大额减仓常要吃穿数档深度，实际成本数倍于第一档价差。用第一档价差估降风险预算，会系统性低估、临场被迫追加。</span></p><p><span class="marginnote">术语翻译：crossing 就是「不再等人来吃我的报价，主动去吃对手的单」。为换取立即成交，你把整个买卖价差付出去，还要消耗多档深度——像急用钱时把藏品折价卖给回收店：快，但折价就是速度的价格。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>阶梯按限额使用率预写进引擎：八成——偏度加倍、逆势侧收窄规模；十成——逆势侧停报，只留减仓方向，同时启动对冲腿；超限或触发止损——主动减仓，按 <a href="/quant/almgren-chriss">Almgren–Chriss</a> 口径切片控制冲击，或转入拍卖与大宗询价。隔夜限额更紧的账，要提前进偏度：尾盘惩罚按日历升高，这是第一课日历调度的对象，等触限才升高惩罚等于没有惩罚。</p><p><span class="marginnote">数字实例：日库存限额 2000 万，则八成（1600 万）触发偏度加倍，十成（2000 万）停逆势侧并启动对冲腿。这套数字必须在开盘前写进引擎并演练过——触限那几秒是「执行预案」的时间，不是「开会讨论」的时间。</span></p><p>降风险的每个动作都要回答「为什么是这个价位能成交」：你的单侧撤单与单向报价是公开可见的，对手读得出你的困境。动作的执行质量本身有市场影响——这就是为什么阶梯从最不暴露的开始。</p>',8)),(e(),n(t,null,{default:a(()=>[r(B,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20USE%5B%22%E9%99%90%E9%A2%9D%E4%BD%BF%E7%94%A8%E7%8E%87%22%5D%20--%3E%7C%2280%25%22%7C%20S1%5B%22%E5%81%8F%E5%BA%A6%E5%8A%A0%E5%80%8D%EF%BC%8C%E9%80%86%E5%8A%BF%E4%BE%A7%E7%BC%A9%E9%87%8F%22%5D%0A%20%20USE%20--%3E%7C%22100%25%22%7C%20S2%5B%22%E9%80%86%E5%8A%BF%E4%BE%A7%E5%81%9C%E6%8A%A5%EF%BC%8C%E5%90%AF%E5%8A%A8%E5%AF%B9%E5%86%B2%E8%85%BF%22%5D%0A%20%20USE%20--%3E%7C%22%E8%B6%85%E9%99%90%E6%88%96%E6%AD%A2%E6%8D%9F%22%7C%20S3%5B%22%E4%B8%BB%E5%8A%A8%E5%87%8F%E4%BB%93%EF%BC%9A%E5%88%87%E7%89%87%E6%8E%A7%E5%88%B6%E5%86%B2%E5%87%BB%22%5D%0A%20%20S3%20--%3E%20S4%5B%22%E6%8B%8D%E5%8D%96%20%2F%20%E5%A4%A7%E5%AE%97%E8%BD%AC%E8%AE%A9%E5%BA%93%E5%AD%98%22%5D%0A%20%20S1%20--%3E%20Q%5B%22%E5%BA%93%E5%AD%98%E5%9B%9E%E8%90%BD%22%5D%0A%20%20S2%20--%3E%20Q%0A%20%20S3%20--%3E%20Q%0A%20%20S4%20--%3E%20Q%0A%20%20Q%20--%3E%20RESUME%5B%22%E6%81%A2%E5%A4%8D%E5%AF%B9%E7%A7%B0%E6%8A%A5%E4%BB%B7%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[i(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>降风险的经济学在 <a href="/quant/ho-stoll-inventory">Ho–Stoll</a> 的框架里就是库存项压过收入项：库存的边际方差成本超过价差边际收入时，最优报价会把一侧推到不成交，甚至主动吃单——1981 年的经销商没有限价簿可退，只剩主动出清。电子市场多了中间选项（单向报价、对冲腿），但角点解的逻辑没变：<a href="/quant/toxic-flow">毒性流</a>讲过，毒性期望损失超过价差时，停报价或只报减仓侧是零利润约束下的理性选择，而不是故障。</p><p>集体维度是边界也是环境：所有做市商同时走同一级台阶时，深度消失、价格发现改走更薄的簿，你自己的减仓成本反而上升。阶梯因此要含拥挤感知：检测到对手单侧撤单抬升时，把 crossing 的预算按深度收缩重估，而不是按旧标价执行。</p><p><span class="marginnote">直觉类比：剧场散场时人人挤向同一个出口，出口反而更堵。所有做市商同时停逆势侧、同时吃单减仓，簿上深度瞬间蒸发，你的「快速出口」crossing 也跟着变贵——拥挤使预案的标价失效，预算要按当下的可见深度重算。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>涨跌停、停牌与熔断使部分路径不可用：停板日 crossing 无法成交，只剩对手方少的拍卖与次日缺口风险。对冲腿自己触限或保证金不足时，阶梯跳级到主动减仓，跳级要允许并演练。长周末与节假日前，隔夜惩罚要提前数小时升高，而不是等尾盘。期权簿的减仓紧迫性随 gamma 体制变化，属于衍生品做市另一条线；本课的阶梯以线性库存为对象。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>触限后的选项按成本-速度谱排序：偏度、单向报价、crossing、对冲、拍卖大宗。</li><li>阶梯按限额使用率预先写进引擎并演练，隔夜惩罚提前进偏度。</li><li>crossing 按逐档消耗核算，第一档价差会低估数倍。</li><li>角点解逻辑来自 Ho–Stoll 与毒性流的停报价口径：库存边际成本压过收入时就退。</li><li>降风险动作有市场影响与拥挤效应，预算按可见深度动态重估。</li><li>出处：Ho and Stoll, <em>Journal of Financial Economics</em>, 1981；Almgren and Chriss, <em>Journal of Risk</em>, 2000；Easley, López de Prado and O&#39;Hara, <em>Review of Financial Studies</em>, 2012。</li></ul>',8))])}const _=o(d,[["render",m]]);export{u as __pageData,_ as default};
